function createErrorProvider(error: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('coerces thrown non-Error values to Error with cause for onError while preserving Error instances and rethrowing unchanged', async () => {
    const originalError = new Error('boom');
    const plainObject = {code: 503, detail: 'upstream down'};
    const rejections: unknown[] = ['string boom', plainObject, undefined, originalError];

    const outcomes = await Promise.all(
      rejections.map(async thrown => {
        const received: Error[] = [];
        const hooks: OrchestratorHooks = {
          onError: async (_session, error) => {
            received.push(error);
          },
        };
        const orchestrator = createChatOrchestrator(createErrorProvider(thrown), promptBuilder, undefined, {hooks});
        const rethrown = await orchestrator
          .processMessage(createSession('hello'))
          .catch((caught: unknown) => caught);
        const recorded = received[0];
        return {
          rethrownSame: rethrown === thrown,
          callCount: received.length,
          isError: recorded instanceof Error,
          sameInstance: recorded === originalError,
          message: recorded?.message,
          cause: recorded?.cause,
        };
      })
    );

    expect(outcomes).toEqual([
      {
        rethrownSame: true,
        callCount: 1,
        isError: true,
        sameInstance: false,
        message: 'string boom',
        cause: 'string boom',
      },
      {
        rethrownSame: true,
        callCount: 1,
        isError: true,
        sameInstance: false,
        message: '{"code":503,"detail":"upstream down"}',
        cause: plainObject,
      },
      {
        rethrownSame: true,
        callCount: 1,
        isError: true,
        sameInstance: false,
        message: 'undefined',
        cause: undefined,
      },
      {
        rethrownSame: true,
        callCount: 1,
        isError: true,
        sameInstance: true,
        message: 'boom',
        cause: undefined,
      },
    ]);
  });
});

