function coerceToError(thrown: unknown): Error {
  if (thrown instanceof Error) return thrown;
  return new Error(formatRejection(thrown), {cause: thrown});
}

function formatRejection(thrown: unknown): string {
  if (typeof thrown === 'string') return thrown;
  if (thrown === null || typeof thrown !== 'object') return String(thrown);
  try {
    return JSON.stringify(thrown) ?? String(thrown);
  } catch (serialiseError) {
    log.warn('orchestrator', 'failed to serialise rejection', {
      reason: serialiseError instanceof Error ? serialiseError.message : String(serialiseError),
    });
    return String(thrown);
  }
}
